import {ANATOMY_EXERCISES,ANATOMY_SOURCES} from './anatomy-data.js';
import {FIGURE_BY_ID} from './figures.js';
import {CHAPTER_BY_ID} from './courses.js';
import {shuffle} from './quiz.js';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const PLANES=['Coupe coronale','Coupe sagittale','Coupe axiale · horizontale'];
export const exerciseForFigure=id=>ANATOMY_EXERCISES.find(e=>e.figures.includes(id));
export function createAnatomySession(figure){
 const f=FIGURE_BY_ID[figure];
 if(!exerciseForFigure(figure))throw new Error('Schéma hors du TD d’anatomie');
 return {figure,active:0,answers:f.parts.map(()=>''),plane:'',requirePlane:Boolean(f.plane),indices:f.parts.map((_,i)=>i),choices:shuffle(f.parts.map(p=>p.label)),revealed:false,result:null};
}
export function anatomyReady(s){return Boolean(s)&&s.indices.every(i=>s.choices.includes(s.answers[i]))&&(!s.requirePlane||PLANES.includes(s.plane));}
export function gradeAnatomySession(s){
 if(!anatomyReady(s))throw new Error('Complète les réponses avant de valider.');
 const f=FIGURE_BY_ID[s.figure],parts=f.parts.map((p,i)=>s.answers[i]===p.label),plane=!f.plane||s.plane===f.plane;
 return {parts,plane,total:parts.length+(f.plane?1:0),correct:parts.filter(Boolean).length+(f.plane&&plane?1:0)};
}
export function retryAnatomySession(s){
 if(!s.revealed||!s.result)throw new Error('Valide avant de reprendre les erreurs.');
 const indices=s.result.parts.flatMap((correct,i)=>correct?[]:[i]);
 const requirePlane=Boolean(FIGURE_BY_ID[s.figure].plane&&!s.result.plane);
 if(!indices.length&&!requirePlane)return createAnatomySession(s.figure);
 return {...s,active:indices[0]??0,indices,requirePlane,answers:s.answers.map((a,i)=>indices.includes(i)?'':a),plane:requirePlane?'':s.plane,choices:shuffle(s.choices),revealed:false,result:null};
}
const sourceLinks=()=>`<details class="anatomy-sources"><summary>Document d’origine et références de la correction</summary><p>Le PDF fourni ne comporte pas de correction écrite. Celle proposée ici reprend les pointes de ses flèches et s’appuie sur des références d’anatomie. Les points sont des repères ; ils ne délimitent pas des aires fonctionnelles.</p>${ANATOMY_SOURCES.map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`).join('')}</details>`;
export function renderAnatomyHome(progress){
 const figures=ANATOMY_EXERCISES.flatMap(e=>e.figures).map(id=>FIGURE_BY_ID[id]);
 const total=figures.reduce((n,f)=>n+f.parts.length,0),done=figures.reduce((n,f)=>n+f.parts.filter((p,i)=>progress.answers[`figure-${f.id}-${i}`]===true).length,0);
 return `<a class="back-link" href="#revision">← Toutes les révisions</a><p class="eyebrow">TD D’ANATOMIE · LIÉ AUX COURS 1 ET 2</p><h1>Du schéma aux bons repères.</h1><p class="page-lead">Les quatre exercices de tes deux pages, dans leur ordre. Choisis le nom à chaque emplacement numéroté, identifie les plans de coupe, puis valide pour voir les réponses et les rôles.</p><p class="anatomy-progress">${done} / ${total} emplacements réussis à la dernière tentative · 7 illustrations du document</p><div class="anatomy-grid">${ANATOMY_EXERCISES.map(e=>`<article class="anatomy-card"><div class="anatomy-card-image"><img src="./assets/diagrams/td-anatomy-${e.image}.webp" alt="Illustration sans correction de l’exercice ${Number(e.number)}" loading="lazy"></div><div class="anatomy-card-copy"><p class="eyebrow">EXERCICE ${e.number} · ${e.figures.length} SCHÉMA${e.figures.length>1?'S':''}</p><h2>${esc(e.title)}</h2><p>${esc(e.subtitle)}</p><a class="primary-button" href="#revision/anatomy/${e.id}">Faire l’exercice →</a><div class="anatomy-course-links">${e.courses.map(id=>{const ch=CHAPTER_BY_ID[id];return `<a href="#cours/${ch.course}/${id}">Revoir : ${esc(ch.kicker)}</a>`;}).join('')}</div></div></article>`).join('')}</div><div class="anatomy-footer"><button class="secondary-button" data-anatomy-theory="all">QCM de repérage et de compréhension →</button><a class="text-button" href="./assets/td-anatomie.pdf" target="_blank" rel="noopener">Ouvrir les deux pages du TD ↗</a></div>${sourceLinks()}`;
}
export function renderAnatomyExercise(s,diagram,figureCredit){
 const f=FIGURE_BY_ID[s.figure],e=exerciseForFigure(f.id),r=s.result;
 const sequence=ANATOMY_EXERCISES.flatMap(e=>e.figures),next=sequence[sequence.indexOf(f.id)+1],nextExercise=next&&exerciseForFigure(next);
 const done=s.indices.filter(i=>s.answers[i]).length+(s.requirePlane&&s.plane?1:0),total=s.indices.length+(s.requirePlane?1:0);
 return `<div class="anatomy-top"><a class="back-link" href="#revision/anatomy">← Les quatre exercices</a><span>TD d’anatomie · exercice ${e.number} / 04</span></div><nav class="anatomy-steps" aria-label="Exercices du TD">${ANATOMY_EXERCISES.map(x=>`<a class="${x.id===e.id?'active':''}" ${x.id===e.id?'aria-current="step"':''} href="#revision/anatomy/${x.id}">${x.number} · ${esc(x.title)}</a>`).join('')}</nav><div class="anatomy-title"><p class="eyebrow">EXERCICE ${e.number}</p><h1>${esc(e.title)}</h1><p>Choisis le nom correspondant à chaque numéro. Le cercle rouge montre le point visé ; les réponses et les rôles apparaissent après validation.</p></div>${e.figures.length>1?`<nav class="anatomy-tabs" aria-label="Schémas de cet exercice">${e.figures.map((id,i)=>`<a href="#revision/anatomy/${e.id}/${id}" class="${id===f.id?'active':''}" ${id===f.id?'aria-current="page"':''}>${e.id==='mri'?'IRM':'Coupe'} ${String.fromCharCode(65+i)}</a>`).join('')}</nav>`:''}<div class="anatomy-exercise-layout"><div class="anatomy-image-panel"><h2>${esc(f.title)}</h2><p class="orientation">${esc(f.orientation)}${s.revealed&&f.plane?' · '+esc(f.plane):''}</p><div id="anatomyDiagram">${diagram(f,{active:s.active,showLabels:false,exercise:true})}</div><p class="figure-note">${esc(f.note)}</p>${figureCredit(f)}${s.revealed?`<a class="text-button" href="#atlas/${f.id}">Observer avec la légende complète ↗</a>`:''}</div><div class="anatomy-answer-panel"><form id="anatomyForm"><div class="anatomy-form-head"><h2>${s.indices.length<f.parts.length?'Reprendre les erreurs':'À toi de légender'}</h2><span id="anatomyFilled">${done} / ${total} réponses choisies</span></div>${s.requirePlane?`<label class="anatomy-plane">D’abord, nomme le plan de coupe<select id="anatomyPlane" ${s.revealed?'disabled':''}><option value="">Choisir le plan…</option>${PLANES.map(p=>`<option value="${esc(p)}" ${s.plane===p?'selected':''}>${esc(p)}</option>`).join('')}</select></label>${s.revealed?`<p class="anatomy-plane-feedback ${r.plane?'correct':'incorrect'}">${r.plane?'✓':'×'} ${esc(f.plane)}</p>`:''}`:''}<div class="anatomy-answers">${s.indices.map(i=>{const p=f.parts[i],correct=r?.parts[i];return `<div data-anatomy-row="${i}" class="anatomy-answer ${i===s.active?'active':''} ${s.revealed?(correct?'correct':'incorrect'):''}"><label for="anatomyAnswer${i}"><button type="button" data-anatomy-part="${i}" aria-label="Montrer le repère ${i+1}">${i+1}</button><span>Repère ${i+1}</span>${s.revealed?`<strong>${correct?'✓ Correct':'× À revoir'}</strong>`:''}</label><select id="anatomyAnswer${i}" data-anatomy-answer="${i}" aria-label="Nom du repère ${i+1}" ${s.revealed?'disabled':''}><option value="">Choisir une structure…</option>${s.choices.map(label=>`<option value="${esc(label)}" ${s.answers[i]===label?'selected':''}>${esc(label)}</option>`).join('')}</select>${s.revealed?`<div class="anatomy-correction"><strong>${esc(p.label)}</strong><p>${esc(p.explain)}</p></div>`:''}</div>`;}).join('')}</div>${s.revealed?'':`<button type="submit" class="primary-button" id="validateAnatomy" ${anatomyReady(s)?'':'disabled'}>Valider mes emplacements →</button><p class="anatomy-hint">${s.requirePlane?'Choisis aussi le plan de coupe. ':''}Tu peux réutiliser un nom si tu hésites. Aucun indice de correction avant validation.</p>`}</form>${s.revealed?`<div class="anatomy-result" tabindex="-1"><p class="eyebrow">CORRECTION PÉDAGOGIQUE</p><h2>${r.correct} / ${r.total} réponses correctes</h2><p>${r.correct===r.total?'Tous les repères et le plan éventuel sont corrects.':(r.total-r.correct)+' réponse'+(r.total-r.correct>1?'s':'')+' à revoir. Relis les noms et les rôles ci-dessus.'}</p><div class="anatomy-result-actions">${r.correct<r.total?'<button class="primary-button" id="retryAnatomy">Reprendre mes erreurs →</button>':''}<button class="secondary-button" id="resetAnatomy">Recommencer le schéma</button>${next?`<a class="text-button" href="#revision/anatomy/${nextExercise.id}/${next}">Schéma suivant →</a>`:'<a class="text-button" href="#revision/anatomy">Retour au TD →</a>'}</div></div>`:''}</div></div>${e.questions?`<div class="anatomy-precision"><h2>V1, A1 et les aires secondaires : changer de vue</h2><p>V1 se situe surtout autour du sillon calcarin, sur la face médiale occipitale. A1 se trouve dans les gyri de Heschl, enfouis dans le sillon latéral. Le prémoteur et la SMA complètent M1 ; les territoires associatifs du TD ne sont pas des aires sensorielles primaires.</p><button class="secondary-button" data-anatomy-theory="areas">Compléter avec les 4 questions →</button><div><a href="#atlas/3d/v1">Voir V1 en vue médiale ↗</a><a href="#atlas/3d/a1">Voir le repère de A1 ↗</a><a href="#atlas/3d/m2">Revoir les aires motrices secondaires ↗</a></div></div>`:''}${sourceLinks()}`;
}
